## Why This Is Asked
This question tests mastery of maintaining order statistics with dynamic updates, handling duplicates efficiently, and implementing lazy deletion—all while achieving O(log n) time complexity.

## Key Concepts
- **Two heaps for median maintenance**: A max-heap stores the lower half, while a min-heap stores the upper half, allowing O(1) median retrieval
- **Duplicate handling**: Store actual values in heaps with a frequency counter map to track occurrences
- **Lazy deletion**: Defer removals by updating a delayed-delete map; prune elements lazily when they surface at heap tops to achieve O(log n) amortized erase

## Code Example
```python
import heapq

class DualHeap:
    def __init__(self):
        self.small = []  # max-heap (store negatives)
        self.large = []  # min-heap
        self.delayed = {}  # lazy deletion map
        self.small_size = 0
        self.large_size = 0

    def prune(self, heap):
        while heap:
            num = -heap[0] if heap is self.small else heap[0]
            if self.delayed.get(num, 0) > 0:
                heapq.heappop(heap)
                self.delayed[num] -= 1
                if self.delayed[num] == 0:
                    del self.delayed[num]
            else:
                break

    def rebalance(self):
        if self.small_size > self.large_size + 1:
            val = -heapq.heappop(self.small)
            self.small_size -= 1
            heapq.heappush(self.large, val)
            self.large_size += 1
        elif self.large_size > self.small_size + 1:
            val = heapq.heappop(self.large)
            self.large_size -= 1
            heapq.heappush(self.small, -val)
            self.small_size += 1

    def insert(self, num):
        if not self.small or num <= -self.small[0]:
            heapq.heappush(self.small, -num)
            self.small_size += 1
        else:
            heapq.heappush(self.large, num)
            self.large_size += 1
        self.rebalance()

    def erase(self, num):
        self.delayed[num] = self.delayed.get(num, 0) + 1
        if num <= -self.small[0]:
            self.small_size -= 1
        else:
            self.large_size -= 1
        self.rebalance()

    def getMedian(self):
        if self.small_size > self.large_size:
            self.prune(self.small)
            return -self.small[0]
        elif self.large_size > self.small_size:
            self.prune(self.large)
            return self.large[0]
        return (-self.small[0] + self.large[0]) / 2
```

## Why This Is Asked
Tests ability to design a compact, eviction-aware data structure for time-windowed counting, a common pattern in real-time analytics.

## Key Concepts
- Sliding window eviction via timestamped events
- Bucketed counts: map from count to set of users for fast top-k
- Invariants: update counts atomically during insertion and eviction
- Complexity: O(log n) updates, O(k log n) top-k retrieval

## Code Example
```javascript
class WindowCounter {
  constructor(W) {
    this.W = W;
    this.count = new Map(); // user -> cnt
    this.buckets = new Map(); // cnt -> Set<user>
    this.events = new Deque(); // (ts, user)
  }
  _addToBucket(cnt, user) {
    if (!this.buckets.has(cnt)) this.buckets.set(cnt, new Set());
    this.buckets.get(cnt).add(user);
  }
  _removeFromBucket(cnt, user) {
    if (!this.buckets.has(cnt)) return;
    this.buckets.get(cnt).delete(user);
    if (this.buckets.get(cnt).size === 0) this.buckets.delete(cnt);
  }
  prune(now) {
    while (this.events.length && this.events.peek().ts <= now - this.W) {
      const {ts, user} = this.events.shift();
      const c = this.count.get(user) || 0;
      if (c > 0) {
        this._removeFromBucket(c, user);
        const nc = c - 1;
        if (nc > 0) {
          this._addToBucket(nc, user);
          this.count.set(user, nc);
        } else {
          this.count.delete(user);
        }
      }
    }
  }
  addEvent(user, ts) {
    this.events.push({ts, user});
    this.prune(ts);
    const c = this.count.get(user) || 0;
    if (c > 0) this._removeFromBucket(c, user);
    const nc = c + 1;
    this._addToBucket(nc, user);
    this.count.set(user, nc);
  }
  topK(now, k) {
    const res = [];
    // iterate counts from high to low
    const counts = Array.from(this.buckets.keys()).sort((a,b)=>b-a);
    for (const cnt of counts) {
      const set = this.buckets.get(cnt);
      const users = Array.from(set).sort((a,b)=>a-b); // tie-breaker by userId
      for (const u of users) {
        res.push([u, cnt]);
        if (res.length === k) return res;
      }
    }
    return res;
  }
}
```

